            ContentJson = """{"title":"General Ledger Field Reference","groups":[{"heading":"Chart of Accounts — account editor","items":[{"label":"Account Number","value":"Your numbering, for example 1000 for cash. Locks once the account has postings."},{"label":"Name","value":"How the account appears on reports and in the account pickers."},{"label":"Type","value":"Asset, Liability, Equity, Income or Expense. Decides which statement the account lands on. Locks once posted to."},{"label":"Normal Balance","value":"Debit or Credit. Assets and expenses are normally Debit; liabilities, equity and income are normally Credit. Locks once posted to."},{"label":"Parent Account","value":"Optional. The account rolls up under its parent on the statements."},{"label":"Cash Flow Category","value":"Operating, Investing, Financing or None. Groups the account on the Cash Flow statement."},{"label":"Requires Job","value":"On: every line posted here must name a job."},{"label":"Requires Cost Center","value":"On: every line posted here must name a cost center."},{"label":"Active","value":"Off retires the account: it keeps its history but is no longer offered when posting."},{"label":"Description","value":"A note about what belongs in the account."},{"label":"Control badge","value":"Marks an account Forge manages for the automatic postings. Not editable here."}]},{"heading":"New Journal Entry","items":[{"label":"Entry date","value":"The date the entry belongs to. Must be in an Open period."},{"label":"Memo","value":"Required. Why the entry exists."},{"label":"Account (line)","value":"Which account the line posts to."},{"label":"Debit / Credit (line)","value":"The amount, in one column only."},{"label":"Description (line)","value":"Optional note for this line alone."},{"label":"Add line / Remove line","value":"Add or remove lines. The editor keeps at least two."},{"label":"Balanced / Out of balance","value":"Whether total debits equal total credits. Posting requires Balanced."},{"label":"Post entry","value":"Posts the entry. Permanent once done."}]},{"heading":"Ledger register","items":[{"label":"Entry #","value":"The entry's permanent number."},{"label":"Source","value":"Where the entry came from: an invoice, payment, bill, payroll run, the opening conversion, a manual entry or a reversal."},{"label":"Memo","value":"The entry's memo."},{"label":"Balance","value":"Running balance after the entry, shown when viewing a single account."},{"label":"Find in ledger","value":"Searches the loaded entries; Enter or the arrows step between matches."},{"label":"Scan for anomalies","value":"Flags manual postings to control accounts and unusually large manual entries. Advice, not errors."},{"label":"Account link (line)","value":"Opens the ledger for that one account. All entries returns to the full register."},{"label":"Explain with AI","value":"Plain-language summary of what an entry did."},{"label":"Reverse","value":"Posts an equal-and-opposite entry on the date you choose, with a required reason. Only offered on a posted entry not already reversed."},{"label":"Correct (new entry)","value":"Opens the editor pre-filled from the original so you can post the right version."},{"label":"Reverses # / Reversed by #","value":"Links between an entry and its reversal."}]},{"heading":"Period Close","items":[{"label":"Open","value":"Postings allowed."},{"label":"SoftClosed","value":"Postings blocked; can be reopened."},{"label":"HardClosed","value":"Postings blocked; cannot be reopened. Shown as Locked."},{"label":"Soft-close / Hard-close / Reopen","value":"Move a period between the states its current status allows."},{"label":"Close year (RE roll)","value":"Posts the retained-earnings roll and hard-closes every period in the year. Asks for confirmation; cannot be undone."}]},{"heading":"Bank Reconciliation","items":[{"label":"Cash account","value":"The ledger cash account being reconciled."},{"label":"Statement date","value":"The closing date on the bank statement."},{"label":"Ending balance","value":"The closing balance on the bank statement."},{"label":"Start","value":"Opens a Draft worksheet."},{"label":"Book (GL) cash balance","value":"The ledger balance of the cash account as of the statement date."},{"label":"Cleared","value":"Total of lines ticked as cleared."},{"label":"Outstanding","value":"Total of lines not yet cleared."},{"label":"Difference","value":"What is still unexplained. Must be zero to finalize."},{"label":"Cleared checkbox","value":"Stages a line as cleared. Nothing is saved until Update cleared."},{"label":"Update cleared","value":"Saves the staged selection and recomputes the totals."},{"label":"Finalize","value":"Locks the worksheet. Enabled only at zero difference with no unsaved changes."},{"label":"Back to list","value":"Returns to the reconciliations list without finalizing."}]},{"heading":"Budgets","items":[{"label":"Year stepper","value":"Which fiscal year you are editing or comparing."},{"label":"Budget Entry","value":"One Budget Amount per income and expense account for the year. Save stores them."},{"label":"Budget vs Actual","value":"Budget, Actual, Variance and Variance % per account for the selected period."},{"label":"Period","value":"A month of the year or the full year, on the Budget vs Actual tab."},{"label":"Variance","value":"Budget minus actual."}]}]}"""
