            AppRoutes = """["/accounting"]""",
            Tags = """["accounting","general-ledger","quiz"]""",
            ContentJson = """{"passingScore":80,"shuffleQuestions":false,"shuffleOptions":true,"showExplanationsAfterSubmit":true,"questions":[{"id":"q1","text":"An admin tries to switch on the full general ledger and Forge refuses. What is the most likely reason?","options":[{"id":"q1a","text":"The opening balances have not been posted yet","isCorrect":true},{"id":"q1b","text":"No budgets have been entered"},{"id":"q1c","text":"The current period is still open"},{"id":"q1d","text":"There are fewer than ten accounts in the chart"}],"explanation":"The full ledger cannot be switched on until the opening journal from the old books is posted for every book, so the ledger starts from a balance that ties to something."},{"id":"q2","text":"You posted a manual entry to the wrong expense account last week. What is the right fix?","options":[{"id":"q2a","text":"Open the entry on the Ledger and edit the account"},{"id":"q2b","text":"Reverse the entry, then post a correction","isCorrect":true},{"id":"q2c","text":"Delete the entry and re-enter it"},{"id":"q2d","text":"Change the account's type so the posting lands in the right place"}],"explanation":"Posted entries never change. Reverse posts an equal-and-opposite entry that links to the original; Correct opens the editor pre-filled so you can post the right version."},{"id":"q3","text":"Which fields on an account lock once it has postings?","options":[{"id":"q3a","text":"Name and Description"},{"id":"q3b","text":"Account Number, Type and Normal Balance","isCorrect":true},{"id":"q3c","text":"Active and Parent Account"},{"id":"q3d","text":"Nothing locks; any field can be edited at any time"}],"explanation":"The structural fields — number, type and normal balance — lock after the first posting. Name, parent, cash flow category, the Requires toggles, Active and Description stay editable."},{"id":"q4","text":"The accountant finds a missing accrual in a month you have already soft-closed. What do you do?","options":[{"id":"q4a","text":"Reopen the period, post the entry, soft-close it again","isCorrect":true},{"id":"q4b","text":"Post the entry dated in the current month and note it in the memo"},{"id":"q4c","text":"Hard-close the period so the problem cannot recur"},{"id":"q4d","text":"Nothing can be done once a period is soft-closed"}],"explanation":"A soft close can be reopened; that is exactly what it is for. Only a hard close is permanent."},{"id":"q5","text":"What does Close year (RE roll) do?","options":[{"id":"q5a","text":"Soft-closes the last period of the year"},{"id":"q5b","text":"Posts the retained-earnings roll and hard-closes every period in the year","isCorrect":true},{"id":"q5c","text":"Deletes the year's budgets"},{"id":"q5d","text":"Finalizes every draft bank reconciliation"}],"explanation":"Year-end close zeroes the income and expense accounts into retained earnings and hard-closes all of the year's periods. It asks for confirmation because it cannot be undone."},{"id":"q6","text":"On a bank reconciliation worksheet you have ticked every line on the statement but the Finalize button is still disabled. Which is NOT a possible reason?","options":[{"id":"q6a","text":"You have not clicked Update cleared yet"},{"id":"q6b","text":"The difference is not zero"},{"id":"q6c","text":"The statement ending balance was typed wrong"},{"id":"q6d","text":"The period has not been hard-closed","isCorrect":true}],"explanation":"Finalize needs a zero difference and no unsaved changes. Period status does not gate it — in fact you reconcile before you close the period, not after."},{"id":"q7","text":"On the Budget vs Actual tab an expense account shows a positive variance. What does that mean?","options":[{"id":"q7a","text":"You spent less than budgeted","isCorrect":true},{"id":"q7b","text":"You spent more than budgeted"},{"id":"q7c","text":"The account has no budget"},{"id":"q7d","text":"The period is closed"}],"explanation":"Variance is budget minus actual, so a positive variance on an expense account means actual spending came in under budget."}]}"""
